create extension if not exists pgcrypto;

create table if not exists public.dev_resources (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 120),
  url text not null unique check (char_length(url) between 1 and 2048),
  domain text not null check (char_length(domain) between 1 and 253),
  category text not null check (char_length(category) between 1 and 80),
  subcategory text check (subcategory is null or char_length(subcategory) between 1 and 100),
  description text not null check (char_length(description) between 1 and 600),
  tags text[] not null default '{}',
  sort_order integer,
  created_at timestamptz not null default now(),
  check (cardinality(tags) <= 8)
);

create index if not exists dev_resources_category_idx
  on public.dev_resources (category);

on conflict (url) do update set
  sort_order = excluded.sort_order,
  name = excluded.name,
  domain = excluded.domain,
  category = excluded.category,
  subcategory = excluded.subcategory,
  description = excluded.description,
  tags = excluded.tags;

revoke all on public.dev_resources from public;

